var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Leading whitespace: the anchored regex rejects " 1kb", so it falls back
    // to parseInt and is interpreted as 1 byte, not 1 kilobyte.
    assert.strictEqual(bytes.parse(' 1kb'), 1);
    // Garbage before the number must not be silently accepted.
    assert.strictEqual(bytes.parse('foo1kb'), null);
    // "1e2kb" is not a valid "<number>kb" string; pristine parses 1 byte via
    // parseInt, not 2 * 1024 from a mid-string match.
    assert.strictEqual(bytes.parse('1e2kb'), 1);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('parses multi-digit values', function () {
    assert.strictEqual(bytes('10kb'), 10240);
    assert.strictEqual(bytes('100MB'), 104857600);
    assert.strictEqual(bytes('-10kb'), -10240);
    assert.strictEqual(bytes('+100kb'), 102400);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps default 2 decimal places when options omit decimalPlaces', function () {
    assert.strictEqual(bytes(1500, {}), '1.46KB');
    assert.strictEqual(bytes(1500, { unitSeparator: ' ' }), '1.46 KB');
    assert.strictEqual(bytes(1234567, { thousandsSeparator: ',' }), '1.18MB');
    assert.strictEqual(bytes(1500, { decimalPlaces: undefined }), '1.46KB');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // null/undefined must hit the documented error, not a TypeError on .length
    assert.throws(function () { ms(null); }, function (err) {
      return err instanceof Error && !(err instanceof TypeError) &&
        err.message === 'val is not a non-empty string or a valid number. val=null';
    });
    assert.throws(function () { ms(undefined); }, function (err) {
      return err instanceof Error && !(err instanceof TypeError) &&
        err.message === 'val is not a non-empty string or a valid number. val=undefined';
    });
    // non-string values with a truthy .length must not be parsed as strings
    assert.throws(function () { ms({ length: 5 }); }, function (err) {
      return err instanceof Error &&
        err.message === 'val is not a non-empty string or a valid number. val={"length":5}';
    });
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('pluralizes values of exactly 1.5 units', function () {
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('keeps the descriptive message when throwing on invalid input', function () {
    assert.throws(
      function () { ms(null); },
      function (err) {
        return err instanceof Error &&
          err.message === 'val is not a non-empty string or a valid number. val=null';
      },
      'expected the original descriptive error message, got: ' +
        (function () { try { ms(null); } catch (e) { return e.message; } })()
    );
  });

  it('keeps the descriptive message for other invalid values', function () {
    assert.throws(
      function () { ms({}); },
      function (err) {
        return err.message === 'val is not a non-empty string or a valid number. val={}';
      }
    );
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The library guards parse() so any string longer than 100 characters
    // is rejected (returns undefined) instead of being parsed.
    var str = '-1' + new Array(101).join(' ') + 'ms'; // 104 chars, still matches the pattern
    assert.strictEqual(str.length, 104);
    assert.strictEqual(ms(str), undefined);
  });
});

