var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    assert.strictEqual(ms('1y'), 31557600000);
    assert.strictEqual(ms('2 yrs'), 2 * 31557600000);
  });
});

var assert = require('assert');
var ms = require('./');

var s = 1000;
var m = s * 60;
var h = m * 60;
var d = h * 24;
var y = d * 365.25;

describe('proof', function () {
  it('parses years as n * y, not n / y', function () {
    assert.strictEqual(ms('1y'), y);
    assert.strictEqual(ms('2 years'), 2 * y);
    assert.strictEqual(ms('-1yr'), -y);
  });

  it('round-trips a year back to 1y via the formatter', function () {
    assert.strictEqual(ms(ms('1y')), '1y');
  });
});
